function loginRedirect(){const next=location.pathname+location.search+location.hash;location.replace('/login?next='+encodeURIComponent(next));}
async function api(url){const r=await fetch(url,{cache:'no-store',credentials:'same-origin'});if(r.status===401){loginRedirect();throw new Error('401');}if(!r.ok)throw new Error(r.status);return r.json();}
async function ensureAdminSession(){const r=await fetch('/api/auth/session',{cache:'no-store',credentials:'same-origin'});if(!r.ok){loginRedirect();return false;}const x=await r.json();adminCSRFToken=x.csrf||'';return true;}
async function adminWriteFetch(url,options={}){const headers=new Headers(options.headers||{});if(adminCSRFToken)headers.set('X-ZentLoop-CSRF',adminCSRFToken);const r=await fetch(url,{...options,headers,credentials:'same-origin'});if(r.status===401){loginRedirect();throw new Error('401');}return r;}
async function logoutAdmin(){try{await adminWriteFetch('/api/auth/logout',{method:'POST'});}catch(e){}location.replace('/login');}
function ipLinkHTML(ip,cls=''){const value=String(ip||'').trim();return value?`<button type="button" class="ip-link ${esc(cls)}" data-ip-link="${esc(value)}">${esc(value)}</button>`:'—';}
function openIPView(ip){const value=String(ip||'').trim();if(!value)return;const hash='#ip/'+encodeURIComponent(value);if(location.hash!==hash)location.hash=hash;else applyAdminView();}

function localDayKey(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function dayStart(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d,0,0,0,0);}
function selectedTimeRange(){const now=new Date();if(selectedDateMode==='all')return {from:'',to:'',label:'All dates',live:false};if(selectedDateMode==='live'){const from=new Date(now);from.setMinutes(0,0,0);from.setHours(from.getHours()-23);return {from:from.toISOString(),to:'',label:'LIVE · 24h',live:true};}let key='';if(selectedDateMode==='today')key=localDayKey(now);else if(selectedDateMode==='yesterday'){const d=new Date(now);d.setDate(d.getDate()-1);key=localDayKey(d);}else if(selectedDateMode.startsWith('day:'))key=selectedDateMode.slice(4);if(!key)return {from:'',to:'',label:'All dates',live:false};const from=dayStart(key),to=new Date(from);to.setDate(to.getDate()+1);const today=localDayKey(now),yd=new Date(now);yd.setDate(yd.getDate()-1);const label=key===today?'Today':key===localDayKey(yd)?'Yesterday':from.toLocaleDateString();return {from:from.toISOString(),to:to.toISOString(),label,live:false};}
function rangeQuery(includeTarget=true){const tr=selectedTimeRange(),q=new URLSearchParams();if(selectedDateMode==='all')q.set('all','1');if(tr.from)q.set('from',tr.from);if(tr.to)q.set('to',tr.to);if(includeTarget&&selectedTarget)q.set('target',selectedTarget);const x=q.toString();return x?'?'+x:'';}
function rangeAmp(includeTarget=true){const q=rangeQuery(includeTarget);return q?'&'+q.slice(1):'';}
function updateRangeLabels(){const tr=selectedTimeRange();document.querySelectorAll('.rangeWindow').forEach(el=>el.textContent=tr.label);if($('viewMode'))$('viewMode').textContent=tr.live?'LIVE':'FILTERED';if($('viewStatus'))$('viewStatus').classList.toggle('paused',!tr.live);}
async function loadAvailableDays(){try{availableDays=await api('/api/available-days');renderDateFilter();}catch(e){console.error(e)}}
function renderDateFilter(){const sel=$('dateFilter');if(!sel)return;const now=new Date(),today=localDayKey(now),yd=new Date(now);yd.setDate(yd.getDate()-1);const yesterday=localDayKey(yd);let html='<option value="live">LIVE · last 24h</option>';for(const key of availableDays){let label=new Date(dayStart(key)).toLocaleDateString();if(key===today)label='Today';else if(key===yesterday)label='Yesterday';html+=`<option value="day:${esc(key)}">${esc(label)}</option>`;}html+='<option value="all">All dates</option>';sel.innerHTML=html;sel.value=selectedDateMode;if(sel.value!==selectedDateMode){selectedDateMode='live';sel.value='live';}updateRangeLabels();}

async function loadInfo(){try{const x=await api('/api/info');$('brand').textContent=x.brand;$('version').textContent=`${x.brand} ${x.version}`;$('proxyMode').textContent=x.proxy_mode||'direct';$('geoStatus').textContent=x.geoip_ready?'ready':(x.geo_enrichment?'waiting':'off');if($('botStatus'))$('botStatus').textContent=x.official_bots_enabled?(x.official_bots_cache_ready?'ready':'waiting'):'off';if($('sshState')){$('sshState').textContent=x.ssh_trap_enabled?`trap enabled · ${x.ssh_trap_addr}`:'optional trap · disabled';$('sshState').classList.toggle('enabled',!!x.ssh_trap_enabled);}}catch(e){}}
async function refresh(){ try {
  const rq=rangeQuery(true),nrq=rangeQuery(false),amp=rangeAmp(true),namp=rangeAmp(false);
  const [o,activity,s,httpEventSet,h,u,rp,c,p,so,ss,sh,sshEventSet,sf,ao,actors,bursts,intel,health,peers,uh]=await Promise.all([
    api('/api/overview'+rq), api('/api/activity'+rq), api('/api/sessions?limit='+lazyLimits.sessions+amp), api('/api/events?limit='+lazyLimits.httpEvents+amp),
    api('/api/history?limit='+lazyLimits.history+amp), api('/api/unknown-paths?limit='+lazyLimits.unknown+namp), api('/api/recent-paths?limit='+lazyLimits.recentPaths+namp),
    api('/api/catchall-hosts?limit='+lazyLimits.catchAll+namp), api('/api/known-probes?limit='+lazyLimits.knownProbes+namp), api('/api/ssh/overview'+nrq),
    api('/api/ssh/sessions?limit='+lazyLimits.sshSessions+namp), api('/api/ssh/history?limit='+lazyLimits.sshHistory+namp), api('/api/ssh/events?limit='+lazyLimits.sshEvents+namp), selectedTimeRange().live?api('/api/ssh/live-feed?session_limit=12&event_limit=10&left_seconds=60'):Promise.resolve([]),
    api('/api/actors/overview'+nrq), api('/api/actors?limit='+lazyLimits.actors+namp), api('/api/bursts?limit='+lazyLimits.bursts+namp), api('/api/intelligence?aggregate=1&limit='+lazyLimits.intel+namp), api('/api/health'), api('/api/integration/peers'), api('/api/untrusted-hosts?limit=100'+namp)
  ]);
  const e=httpEventSet||[],se=sshEventSet||[];
  renderOverview(o); renderSessions(s); recentEvents=e; renderEvents(recentEvents); activityTimeline=activity;
  renderChart(activityTimeline); historyRows=h; renderHistory(); renderUnknown(u); renderRecentPaths(rp); renderCatchAll(c); renderKnownProbes(p); updateTargets(o.top_targets||[]);
  renderSSHOverview(so); renderSSHSessions(ss); renderSSHHistory(sh); sshRecentEvents=se; renderSSHEvents(se); setSSHLiveFeed(selectedTimeRange().live?sf:[]); renderActorOverview(ao); renderActors(actors); renderBursts(bursts); renderIntel(intel); renderHealth(health); renderIntegrationPeers(peers); renderUntrustedHosts(uh);
  noteLoaded('sessions',s.length);noteLoaded('httpEvents',e.length);noteLoaded('history',h.length);noteLoaded('unknown',u.length);noteLoaded('recentPaths',rp.length);noteLoaded('catchAll',(c&&c.hosts||[]).length);noteLoaded('knownProbes',p.length);noteLoaded('sshSessions',ss.length);noteLoaded('sshHistory',sh.length);noteLoaded('sshEvents',se.length);noteLoaded('actors',actors.length);noteLoaded('bursts',bursts.length);noteLoaded('intel',intel.length);
  updateRangeLabels();
} catch(e) { console.error(e); } }

function renderOverview(o){
  $('hostile').textContent=o.hostile;$('suspicious').textContent=o.suspicious;$('benign').textContent=o.benign;$('requestsToday').textContent=o.requests_today.toLocaleString();$('rps').textContent=o.requests_per_sec.toFixed(1);$('avgDepth').textContent=o.avg_depth.toFixed(1);$('loops').textContent=o.loops_total;
  if($('hostileSplit'))$('hostileSplit').textContent=`web ${o.web_hostile||0} · ssh ${o.ssh_hostile||0}`;if($('suspiciousSplit'))$('suspiciousSplit').textContent=`web ${o.web_suspicious||0} · ssh ${o.ssh_suspicious||0}`;if($('benignSplit'))$('benignSplit').textContent=`web ${o.web_benign||0} · ssh ${o.ssh_benign||0}`;
  $('automated').textContent=o.automated;$('human').textContent=o.human;$('unknown').textContent=o.unknown;const t=o.automated+o.human+o.unknown;$('actorTotal').textContent=t;
  const a=t?o.automated/t*100:0,h=t?o.human/t*100:0;$('actorRing').style.background=`conic-gradient(var(--cyan) 0 ${a}%, var(--ok) ${a}% ${a+h}%, #39434a ${a+h}% 100%)`;
  renderBars('topPaths',o.top_paths,30);renderCountryBars(o.top_countries);renderBars('topReferrers',o.top_referrers,30);renderBars('topTargets',o.top_targets,36);
}
function renderBars(id,rows,n=30){const max=Math.max(1,...(rows||[]).map(x=>x.count));$(id).innerHTML=(rows||[]).map(x=>`<div class="bar-row"><label title="${esc(x.name)}">${esc(short(x.name,n))}</label><div class="bar-track"><i style="width:${x.count/max*100}%"></i></div><b>${x.count}</b></div>`).join('')||'<small>No data yet</small>';}
function renderCountryBars(rows){const mapped=(rows||[]).map(x=>({name:countryLabel(x.name),count:x.count}));renderBars('topCountries',mapped,30);}
function viaLabel(s){return s.proxy==='cloudflare'?'CF'+(s.cloudflare_colo?'/'+s.cloudflare_colo:''):s.proxy==='generic'?'PROXY':'DIRECT';}
function riskClass(s){return s.risk_score>=60?'hot':s.risk_score>=30?'mid':'';}
function compactLiveSessions(rows){const groups=new Map();(rows||[]).forEach(s=>{const key=s.ip||s.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s)});const out=[];for(const group of groups.values()){group.sort((a,b)=>new Date(b.last_seen)-new Date(a.last_seen));if(group.length<3){out.push(...group.map(s=>({...s,_groupCount:1})));continue}const latest=group[0],vias=[...new Set(group.map(viaLabel))];out.push({...latest,_groupCount:group.length,_groupIds:group.map(x=>x.id),risk_score:Math.max(...group.map(x=>x.risk_score||0)),automation_score:Math.max(...group.map(x=>x.automation_score||0)),request_count:group.reduce((n,x)=>n+(x.request_count||0),0),depth:Math.max(...group.map(x=>x.depth||0)),loop:Math.max(...group.map(x=>x.loop||0)),host_sweep:group.some(x=>x.host_sweep),host_sweep_hosts:Math.max(...group.map(x=>x.host_sweep_hosts||0)),actor:group.some(x=>x.actor==='automated')?'automated':latest.actor,_groupVia:vias.join(', ')})}return out.sort((a,b)=>new Date(b.last_seen)-new Date(a.last_seen))}
function liveReferenceTime(s,kind){if(kind==='ssh'&&!s.active&&s.disconnected_at)return s.disconnected_at;return s.last_seen||s.disconnected_at||s.first_seen||new Date().toISOString();}
function liveRowState(s,kind){const age=Math.max(0,Date.now()-new Date(liveReferenceTime(s,kind)).getTime());const active=kind==='ssh'?!!s.active:age<=WEB_ACTIVE_GRACE_MS;return {active,age,label:active?'ACTIVE':`LEFT ${Math.min(59,Math.floor(age/1000))}s`,cls:active?'active':'left'};}
function recentLiveRows(rows,kind){return (rows||[]).filter(s=>{const st=liveRowState(s,kind);return st.active||st.age<=LIVE_RECENT_WINDOW_MS;}).sort((a,b)=>{const as=liveRowState(a,kind),bs=liveRowState(b,kind);if(as.active!==bs.active)return bs.active?1:-1;return new Date(b.last_seen||b.disconnected_at||0)-new Date(a.last_seen||a.disconnected_at||0);});}
function upsertLiveRow(rows,session){if(!session||!session.id)return rows||[];const out=(rows||[]).filter(x=>x.id!==session.id);out.push(session);return out;}
function sshLoginOnlySession(s){return !!s&&(s.auth_attempts||0)>0&&!s.auth_accepted&&!s.shell_opened&&!(s.exec_requests||0)&&!(s.command_count||0);}
function compactSSHLoginBursts(rows){const passthrough=[],groups=new Map();for(const s of rows||[]){if(!sshLoginOnlySession(s)){passthrough.push(s);continue;}const key=`${s.ip||'—'}|${s.username||'—'}|${sshClientLabel(s.client_version)}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);}for(const [key,group] of groups){group.sort((a,b)=>new Date(b.last_seen||b.first_seen)-new Date(a.last_seen||a.first_seen));if(group.length<3){passthrough.push(...group);continue;}const latest=group[0],firstMs=Math.min(...group.map(x=>new Date(x.first_seen||x.last_seen).getTime()).filter(Number.isFinite)),lastMs=Math.max(...group.map(x=>new Date(x.last_seen||x.disconnected_at||x.first_seen).getTime()).filter(Number.isFinite)),active=group.some(x=>x.active),authAttempts=group.reduce((n,x)=>n+(x.auth_attempts||0),0),span=Math.max(1,Math.ceil((lastMs-firstMs)/1000));passthrough.push({...latest,active,first_seen:new Date(firstMs).toISOString(),last_seen:new Date(lastMs).toISOString(),disconnected_at:active?'':(latest.disconnected_at||latest.last_seen),auth_attempts:authAttempts,_loginBurst:true,_groupCount:group.length,_groupIds:group.map(x=>x.id),_burstSpanSeconds:span,_liveKey:`ssh-burst:${key}`,_openId:latest.id,last_action:`${group.length} login sessions · ${authAttempts} rejected auth · ${span}s window`});}return passthrough.sort((a,b)=>{const as=liveRowState(a,'ssh'),bs=liveRowState(b,'ssh');if(as.active!==bs.active)return bs.active?1:-1;return new Date(b.last_seen||b.disconnected_at||0)-new Date(a.last_seen||a.disconnected_at||0);});}
function liveDisplayRows(kind,rows){return kind==='ssh'?compactSSHLoginBursts(rows):rows;}
function liveSessionBox(kind){return $(kind==='ssh'?'liveSSHSessions':'liveWebSessions');}
function liveSessionAttr(kind){return kind==='ssh'?'data-live-ssh-id':'data-live-web-id';}
function liveSessionRows(kind){return kind==='ssh'?sshLiveRows:webLiveRows;}
function setLiveSessionRows(kind,rows){if(kind==='ssh')sshLiveRows=rows;else webLiveRows=rows;}
function liveSessionKey(s){return s?._liveKey||s?.id||'';}
function liveSessionOpenId(s){return s?._openId||s?.id||'';}
function liveSessionRowInnerHTML(kind,s,st){if(kind==='ssh'){const metric=s._loginBurst?`<span class="live-row-metric cmd-metric"><small>TRY</small><b>×${s._groupCount||0}</b></span>`:`<span class="live-row-metric cmd-metric"><small>CMD</small><b>${s.command_count||0}</b></span>`,current=s._loginBurst?(s.last_action||`${s._groupCount||0} login sessions`):(s.current_command||s.last_action||'waiting for activity');return `${ipLinkHTML(s.ip,'live-row-ip')}<span class="live-row-country">${esc(s.country||'—')}</span><span class="live-row-user">${esc(s.username||'—')}</span><span class="live-row-client" title="${esc(sshClientLabel(s.client_version))}">${esc(short(sshClientLabel(s.client_version),25))}</span><span class="live-row-state ${st.cls}">${esc(st.label)}</span>${metric}<span class="live-row-current" title="${esc(current)}">${esc(short(current,58))}</span><span class="live-row-open" aria-hidden="true">›</span>`;}return `${ipLinkHTML(s.ip,'live-row-ip')}<span class="live-row-country">${esc(s.country||'—')}</span><span class="live-row-target" title="${esc(targetLabel(s))}">${esc(short(targetLabel(s),34))}</span><span class="live-row-state ${st.cls}">${esc(st.label)}</span><span class="live-row-metric risk-metric"><small>RISK</small><b class="risk ${riskClass(s)}">${s.risk_score||0}</b></span><span class="live-row-metric req-metric"><small>REQ</small><b>${s.request_count||0}</b></span><span class="live-row-current" title="${esc(s.current_path||'/')}">${esc(short(s.current_path||'/',58))}</span><span class="live-row-open" aria-hidden="true">›</span>`;}
function bindLiveSessionRow(row,kind){const open=()=>{const id=row.dataset.liveOpenId||row.getAttribute(liveSessionAttr(kind));if(kind==='ssh')openSSHSession(id);else openSession(id);};row.onclick=open;row.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open();}};}
function upsertLiveSessionElement(kind,s){const box=liveSessionBox(kind);if(!box||!s)return;const attr=liveSessionAttr(kind),key=liveSessionKey(s);let row=[...box.querySelectorAll(`[${attr}]`)].find(x=>x.getAttribute(attr)===key);const created=!row;if(!row){row=document.createElement('article');row.setAttribute(attr,key);row.tabIndex=0;box.appendChild(row);}row.dataset.liveOpenId=liveSessionOpenId(s);const st=liveRowState(s,kind);row.className=`live-session-row ${kind} ${st.cls}${s._loginBurst?' login-burst':''}`;row.innerHTML=liveSessionRowInnerHTML(kind,s,st);if(s._loginBurst)row.title=`${s._groupCount} repeated SSH login sessions from ${s.ip} as ${s.username||'—'}; opens the latest retained session.`;else row.removeAttribute('title');if(created)bindLiveSessionRow(row,kind);}
function updateLiveSessionSummary(kind,rows){const active=rows.filter(s=>liveRowState(s,kind).active).length,left=rows.length-active;if(kind==='ssh'){if($('liveSSHCount'))$('liveSSHCount').textContent=rows.length;if($('liveSSHSummaryNote'))$('liveSSHSummaryNote').textContent=`${active} active · ${left} recently left`;if($('liveSSHSessionCount'))$('liveSSHSessionCount').textContent=`${active} active · ${left} left`;if($('liveViewLauncherSummary'))$('liveViewLauncherSummary').textContent=`${active} live`;}else{if($('liveWebCount'))$('liveWebCount').textContent=rows.length;if($('liveWebSummaryNote'))$('liveWebSummaryNote').textContent=`${active} active · ${left} recently left`;if($('liveWebSessionCount'))$('liveWebSessionCount').textContent=`${active} active · ${left} left`;}}
function reorderLiveSessionElements(kind,rows){const box=liveSessionBox(kind);if(!box)return;const attr=liveSessionAttr(kind),keep=new Set(rows.map(liveSessionKey));box.querySelectorAll(`[${attr}]`).forEach(row=>{if(!keep.has(row.getAttribute(attr)))row.remove();});if(!rows.length){if(!box.querySelector('.live-empty'))box.innerHTML=`<div class="live-empty">No ${kind==='ssh'?'SSH':'Web'} activity in the last 60 seconds.</div>`;return;}box.querySelectorAll('.live-empty').forEach(x=>x.remove());const current=[...box.querySelectorAll(`[${attr}]`)].map(row=>row.getAttribute(attr)),wanted=rows.map(liveSessionKey);if(current.length!==wanted.length||current.some((id,i)=>id!==wanted[i])){const byId=new Map([...box.querySelectorAll(`[${attr}]`)].map(row=>[row.getAttribute(attr),row]));for(const id of wanted){const row=byId.get(id);if(row)box.appendChild(row);}}}
function syncLiveSessionCollection(kind,rows){const raw=recentLiveRows(rows,kind),display=liveDisplayRows(kind,raw);setLiveSessionRows(kind,raw);for(const s of display)upsertLiveSessionElement(kind,s);reorderLiveSessionElements(kind,display);updateLiveSessionSummary(kind,raw);}
function updateLiveSessionSnapshot(kind,session){const raw=recentLiveRows(upsertLiveRow(liveSessionRows(kind),session),kind),display=liveDisplayRows(kind,raw);setLiveSessionRows(kind,raw);for(const s of display)upsertLiveSessionElement(kind,s);reorderLiveSessionElements(kind,display);updateLiveSessionSummary(kind,raw);}
function updateLiveSessionAges(){for(const kind of ['ssh','web']){const raw=recentLiveRows(liveSessionRows(kind),kind),display=liveDisplayRows(kind,raw);setLiveSessionRows(kind,raw);const box=liveSessionBox(kind),attr=liveSessionAttr(kind);if(box){for(const s of display){const key=liveSessionKey(s);let row=[...box.querySelectorAll(`[${attr}]`)].find(x=>x.getAttribute(attr)===key);if(!row){upsertLiveSessionElement(kind,s);row=[...box.querySelectorAll(`[${attr}]`)].find(x=>x.getAttribute(attr)===key);}if(!row)continue;const st=liveRowState(s,kind),status=row.querySelector('.live-row-state');row.classList.toggle('active',st.active);row.classList.toggle('left',!st.active);if(status){status.textContent=st.label;status.className=`live-row-state ${st.cls}`;}}reorderLiveSessionElements(kind,display);}updateLiveSessionSummary(kind,raw);}}
