function updateTargets(rows){const values=(rows||[]).map(x=>x.name).filter(x=>x&&x!=="(unknown)");knownTargets=values;const sel=$("targetFilter");const current=selectedTarget;sel.innerHTML='<option value="">All targets</option>'+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');sel.value=current;}
