function eventHTML(e){const probe=[e.probe_name,e.probe_cve].filter(Boolean).join(" · ");return `<div class="event ${esc(e.classification)}"><time>${new Date(e.at).toLocaleTimeString()}</time><button type="button" class="ip-link ip" data-ip-link="${esc(e.ip||'')}" title="Open IP intelligence · Target: ${esc(targetLabel(e))}">${esc(short(e.ip,16))}</button><span class="method">${esc(e.method)}</span><span class="e-path" title="${esc(probe||e.path)}">${esc(e.path)}${probe?` <small>· ${esc(probe)}</small>`:''}</span><b class="status">${e.status}</b></div>`}
function sshActivityEvent(e){return ['connect','auth','shell','exec','command','request'].includes(String(e?.type||'').toLowerCase());}
function niceChartMax(value){return Math.max(1,Math.ceil(Number(value)||0));}
function chartTimeLabel(iso,unit){const d=new Date(iso);if(unit==='day'){const dd=String(d.getDate()).padStart(2,'0'),mm=String(d.getMonth()+1).padStart(2,'0');return `${dd}.${mm}.`;}return d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});}
function renderDualTimeline(svg,data,unit){if(!svg)return;const rows=data||[],web=rows.map(x=>Number(x.http||0)),ssh=rows.map(x=>Number(x.ssh||0)),peak=Math.max(0,...web,...ssh),max=niceChartMax(peak),left=38,right=596,top=8,bottom=145,plotH=bottom-top,plotW=right-left,x=i=>rows.length<=1?right:left+i/(rows.length-1)*plotW,y=v=>bottom-(v/max)*plotH;let grid='';const ticks=max<=3?[max,0]:[max,Math.round(max/2),0].filter((v,i,a)=>a.indexOf(v)===i);for(const value of ticks){const yy=y(value);grid+=`<line class="gridline" x1="${left}" y1="${yy}" x2="${right}" y2="${yy}"/><text class="chart-axis-label" x="${left-6}" y="${yy+3}" text-anchor="end">${value.toLocaleString()}</text>`;}if(!rows.length||peak===0){svg.innerHTML=grid+(rows.length?'':'<text x="315" y="82" text-anchor="middle" class="chart-empty">No retained activity.</text>');return;}const series=(arr,kind)=>{const active=arr.map((v,i)=>({v,i})).filter(p=>p.v>0);if(!active.length)return '';if(active.length===1){const p=active[0],xx=x(p.i),yy=y(p.v);return `<line class="chart-spike ${kind}" x1="${xx}" y1="${bottom}" x2="${xx}" y2="${yy}"/><circle class="chart-point ${kind}" cx="${xx}" cy="${yy}" r="4"/>`;}const pts=arr.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<polygon class="chart-fill ${kind}" points="${left},${bottom} ${pts} ${right},${bottom}"/><polyline class="chart-line ${kind}" points="${pts}"/>`};svg.innerHTML=grid+series(web,'web')+series(ssh,'ssh');}
function renderChart(timeline){const rows=timeline?.buckets||[];renderDualTimeline($('activityChart'),rows,'hour');if($('activityFirst'))$('activityFirst').textContent=rows.length?chartTimeLabel(rows[0].at,'hour'):'older';if($('activityLast'))$('activityLast').textContent=rows.length?chartTimeLabel(rows[rows.length-1].at,'hour'):'now';if($('activityUnit'))$('activityUnit').textContent='events / hour';}
function applyRealtimeActivity(proto,e){if(!activityTimeline||!selectedTimeRange().live||!e?.at)return;const ms=new Date(e.at).getTime(),rows=activityTimeline.buckets||[];for(const b of rows){const start=new Date(b.at).getTime();if(ms>=start&&ms<start+3600000){if(proto==='web')b.http=(Number(b.http)||0)+1;else if(sshActivityEvent(e))b.ssh=(Number(b.ssh)||0)+1;renderChart(activityTimeline);return;}}}

