function sshEventHTML(e){const main=e.command||e.message||e.type;const meta=[e.username,e.command_family,e.command_intent,e.command_target?`target:${e.command_target}`:''].filter(Boolean).join(' · ');const jump=`data-ssh-session="${esc(e.session_id||'')}" data-ssh-event="${esc(e.id||'')}"`;const ip=e.ip?`<button type="button" class="ip-link ip" data-ip-link="${esc(e.ip)}" title="Open IP intelligence">${esc(short(e.ip,16))}</button>`:'—';const command=`<span class="ssh-command" title="${esc(main)}">${esc(short(main,62))}${meta?` <small>· ${esc(meta)}</small>`:''}</span>`;return `<div class="ssh-event openable-event" ${jump} tabindex="0" role="button" title="Open SSH transcript at this event"><time>${new Date(e.at).toLocaleTimeString()}</time>${ip}<span class="ssh-type" title="${esc((e.type||'').toUpperCase())}">${esc(sshLiveEventLabel(e.type))}</span>${command}<b>D${e.depth||0}</b></div>`}
