function setSSHLiveFeed(rows){sshLiveFeedState=new Map();(rows||[]).forEach(x=>sshLiveFeedState.set(x.session.id,{session:x.session,events:(x.events||[]).slice(-10)}));renderSSHLiveFeed();}
function applySSHLiveFeedEvent(e,snapshot=null){let x=sshLiveFeedState.get(e.session_id);if(!x)x={session:{id:e.session_id,ip:e.ip,country:e.country||'',username:e.username||'',client_version:e.client_version||'',first_seen:e.at,last_seen:e.at,active:e.type!=='disconnect'&&e.type!=='handshake_error'&&e.type!=='limit',depth:e.depth||0,command_count:0,last_action:e.command||e.message||e.type},events:[]};if(snapshot)x.session=snapshot;else{const ss=x.session;ss.ip=e.ip||ss.ip;ss.country=e.country||ss.country;ss.username=e.username||ss.username;ss.client_version=e.client_version||ss.client_version;ss.last_seen=e.at;ss.depth=Math.max(ss.depth||0,e.depth||0);ss.last_action=e.command||e.message||e.type;if(e.command&&(e.type==='command'||e.type==='exec'))ss.command_count=(ss.command_count||0)+1;if(e.type==='connect'||e.type==='shell')ss.active=true;if(['disconnect','handshake_error','limit'].includes(e.type)){ss.active=false;ss.disconnected_at=e.at;}}if(!x.events.some(row=>row.id===e.id))x.events.push(e);x.events=x.events.slice(-10);sshLiveFeedState.set(e.session_id,x);upsertSSHLiveFeedCard(e.session_id);syncSSHLiveFeedOrder();updateSSHLiveFeedSummary();const card=findSSHLiveFeedCard(e.session_id),box=card?.querySelector('.ssh-live-card-events');if(box)requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight;});}
function httpTimelineStepHTML(e){const probe=[e.probe_name,e.probe_cve].filter(Boolean).join(' · ');const meta=[e.method||'GET',e.status||'—',`risk ${e.risk_score||0}`,`D${e.depth||0}`,`L${e.loop||0}`,e.persona||'',probe].filter(Boolean).join(' · ');return `<div class="transcript-step" data-http-timeline-event="${esc(e.id||'')}"><small>${esc(dt(e.at))} · ${esc(meta)}</small><b>${esc(e.path||'/')}</b>${e.message||e.category?`<span>${esc([e.category,e.message].filter(Boolean).join(' · '))}</span>`:''}</div>`;}
function fillWebSessionMeta(s){$('dId').textContent=s.id||'—';$('dIp').innerHTML=ipLinkHTML(s.ip);$('dProxy').textContent=s.proxy||'direct';$('dIpSource').textContent=s.ip_source||'—';$('dCountry').textContent=countryLabel(s.country);$('dCountrySource').textContent=s.country_source||'—';$('dLanding').textContent=s.visit_first_path||s.first_path||'—';$('dReferrer').textContent=s.last_referrer||s.first_referrer||'—';$('dReferrerHost').textContent=s.referrer_host||'—';$('dTarget').textContent=targetLabel(s);$('dRequestHost').textContent=s.request_host||'—';$('dTargetTrust').textContent=s.target_trust||'untrusted';$('dHostSweep').textContent=s.host_sweep?`yes · ${s.host_sweep_hosts||0} hosts`:'no';$('dOrigin').textContent=s.origin||'—';$('dLanguage').textContent=s.accept_language||'—';$('dHTTP').textContent=s.http_protocol||'—';$('dIntegration').textContent=s.integration||'—';$('dIntegrationTrust').textContent=s.integration_trust||'—';$('dCatchAll').textContent=s.catch_all?'yes':'no';$('dRay').textContent=s.cloudflare_ray||'—';$('dClass').textContent=s.classification||'—';$('dRisk').textContent=(s.risk_score||0)+'/100';$('dActor').textContent=s.actor||'—';$('dBot').textContent=s.bot_claimed?[s.bot_provider,s.bot_name].filter(Boolean).join(' / ')||'claimed':'none';$('dBotVerified').textContent=s.bot_verified?'verified':'no';$('dAuto').textContent=(s.automation_score||0)+'%';$('dConfidence').textContent=s.confidence||'—';$('dInterval').textContent=s.avg_interval_ms?duration(s.avg_interval_ms):'—';$('dVariance').textContent=s.interval_variance_ms?duration(s.interval_variance_ms):'—';$('dReq').textContent=s.visit_request_count||0;$('dReqTotal').textContent=s.request_count||0;$('dVisits').textContent=s.visit_count||1;$('dVisitStarted').textContent=dt(s.visit_started||s.first_seen);$('dVisitContext').textContent=`CURRENT VISIT · ${s.visit_count||1} OF ${s.visit_count||1}`;$('dFirst').textContent=dt(s.first_seen);$('dLast').textContent=dt(s.last_seen);$('dDepth').textContent=s.depth||0;$('dFrustration').textContent=s.frustration||0;$('dUa').textContent=s.user_agent||'—';$('dAutoBar').style.width=Math.max(0,Math.min(100,s.automation_score||0))+'%';}
