function httpDrawerAtBottom(){const d=$('drawer');return d.scrollHeight-d.scrollTop-d.clientHeight<90;}
function followHTTPDrawer(){httpDrawerPending=0;$('httpNewEvents').hidden=true;const d=$('drawer');d.scrollTop=d.scrollHeight;}
function appendOpenWebEvent(e,snapshot=null){if(!openWebSessionId||e.session_id!==openWebSessionId||!$('drawer').classList.contains('open'))return;const atBottom=httpDrawerAtBottom();if(!openWebSessionData)return;openWebSessionData.events=openWebSessionData.events||[];const ss=openWebSessionData.session,currentVisit=e.session_visit_started||ss.visit_started;if(currentVisit&&ss.visit_started&&currentVisit!==ss.visit_started){openWebSessionData.events=[];$('httpTimeline').innerHTML='';httpDrawerPending=0;$('httpNewEvents').hidden=true;ss.visit_started=currentVisit;ss.visit_request_count=0;}if(!openWebSessionData.events.some(x=>x.id===e.id)){openWebSessionData.events.push(e);$('httpTimeline').insertAdjacentHTML('beforeend',httpTimelineStepHTML(e));}if(snapshot){openWebSessionData.session=snapshot;fillWebSessionMeta(snapshot);}else{ss.last_seen=e.at;ss.current_path=e.path||ss.current_path;ss.last_method=e.method||ss.last_method;ss.last_status=e.status||ss.last_status;ss.request_count=Math.max(ss.request_count||0,e.session_requests||0);ss.visit_count=Math.max(ss.visit_count||1,e.session_visits||1);ss.visit_request_count=Math.max(ss.visit_request_count||0,e.session_visit_requests||0);ss.visit_started=e.session_visit_started||ss.visit_started;ss.depth=Math.max(ss.depth||0,e.depth||0);ss.loop=Math.max(ss.loop||0,e.loop||0);ss.frustration=Math.max(ss.frustration||0,e.frustration||0);ss.risk_score=Math.max(ss.risk_score||0,e.risk_score||0);ss.automation_score=e.automation_score??ss.automation_score;ss.classification=e.classification||ss.classification;ss.actor=e.actor||ss.actor;ss.persona=e.persona||ss.persona;fillWebSessionMeta(ss);}if(atBottom){requestAnimationFrame(()=>{$('drawer').scrollTop=$('drawer').scrollHeight;});}else{httpDrawerPending++;const b=$('httpNewEvents');b.hidden=false;b.textContent=`${httpDrawerPending} new live request${httpDrawerPending===1?'':'s'} ↓`;}}function sshLiveFeedRows(){for(const [id,x] of sshLiveFeedState){const st=sshSessionStatus(x.session);if(st.cls!=='live'&&st.cls!=='left')sshLiveFeedState.delete(id);}return [...sshLiveFeedState.values()].sort((a,b)=>{if(!!a.session.active!==!!b.session.active)return b.session.active?1:-1;return new Date(b.session.last_seen||b.session.disconnected_at||0)-new Date(a.session.last_seen||a.session.disconnected_at||0);});}
function findSSHLiveFeedCard(id){const box=$('sshLiveFeed');if(!box)return null;return [...box.querySelectorAll('[data-ssh-id]')].find(card=>card.dataset.sshId===id)||null;}
function sshLiveEventLabel(type){const t=String(type||'').toUpperCase();return t==='HANDSHAKE_ERROR'?'HANDSHAKE':t;}
function sshLiveFeedCardInnerHTML(x){const s=x.session,st=sshSessionStatus(s),events=(x.events||[]).slice(-4);return `<div class="ssh-live-card-head compact"><div class="ssh-live-meta-main">${ipLinkHTML(s.ip,'ssh-feed-ip')}<span>${esc(s.country||'—')}</span><span>${esc(s.username||'—')}</span></div><div class="ssh-live-card-actions"><span class="ssh-live-state ${st.cls}">${esc(st.label)}</span><button type="button">View session</button></div><div class="ssh-live-meta-sub"><span title="${esc(sshClientLabel(s.client_version))}">${esc(short(sshClientLabel(s.client_version),24))}</span><span>D${s.depth||0} · CMD ${s.command_count||0}</span></div></div><div class="ssh-live-card-events compact">${events.map(e=>`<div><time>${new Date(e.at).toLocaleTimeString()}</time><span title="${esc((e.type||'').toUpperCase())}">${esc(sshLiveEventLabel(e.type))}</span><b title="${esc(e.command||e.message||e.type)}">${esc(short(e.command||e.message||e.type,72))}</b></div>`).join('')||'<small>No retained activity yet.</small>'}</div>`;}
function bindSSHLiveFeedCard(card){const open=()=>openSSHSession(card.dataset.sshId);card.querySelector('.ssh-live-card-actions button').onclick=ev=>{ev.stopPropagation();open();};card.onclick=open;card.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open();}};}
function upsertSSHLiveFeedCard(id){const box=$('sshLiveFeed'),x=sshLiveFeedState.get(id);if(!box||!x)return;let card=findSSHLiveFeedCard(id),created=!card;if(!card){card=document.createElement('article');card.dataset.sshId=id;card.tabIndex=0;box.appendChild(card);}const st=sshSessionStatus(x.session);card.className=`ssh-live-card compact ${st.cls}`;card.innerHTML=sshLiveFeedCardInnerHTML(x);if(created)bindSSHLiveFeedCard(card);else{const button=card.querySelector('.ssh-live-card-actions button');if(button)button.onclick=ev=>{ev.stopPropagation();openSSHSession(card.dataset.sshId);};}}
function updateSSHLiveFeedSummary(all=sshLiveFeedRows()){const live=all.filter(x=>x.session.active).length,left=all.length-live;if($('sshLiveFeedSummary'))$('sshLiveFeedSummary').textContent=`${live} live · ${left} recently left`;if($('liveViewLauncherSummary'))$('liveViewLauncherSummary').textContent=`${live} live`;}
function syncSSHLiveFeedOrder(all=sshLiveFeedRows()){const box=$('sshLiveFeed');if(!box)return;const keep=new Set(all.map(x=>x.session.id));box.querySelectorAll('[data-ssh-id]').forEach(card=>{if(!keep.has(card.dataset.sshId))card.remove();});const current=[...box.querySelectorAll('[data-ssh-id]')].map(card=>card.dataset.sshId),wanted=all.map(x=>x.session.id);if(current.length!==wanted.length||current.some((id,i)=>id!==wanted[i])){const byId=new Map([...box.querySelectorAll('[data-ssh-id]')].map(card=>[card.dataset.sshId,card]));for(const id of wanted){const card=byId.get(id);if(card)box.appendChild(card);}}const empty=box.querySelector('.live-empty-feed');if(!all.length){if(!empty){const node=document.createElement('small');node.className='live-empty-feed';node.textContent='No recent SSH sessions in the last 60 seconds.';box.appendChild(node);}else empty.textContent='No recent SSH sessions in the last 60 seconds.';}else if(empty)empty.remove();}
function updateSSHLiveFeedAges(){const all=sshLiveFeedRows();for(const x of all){const card=findSSHLiveFeedCard(x.session.id);if(!card)continue;const st=sshSessionStatus(x.session),status=card.querySelector('.ssh-live-state');card.classList.toggle('live',st.cls==='live');card.classList.toggle('left',st.cls==='left');if(status){status.textContent=st.label;status.className=`ssh-live-state ${st.cls}`;}}syncSSHLiveFeedOrder(all);updateSSHLiveFeedSummary(all);}
function renderSSHLiveFeed(){const box=$('sshLiveFeed');if(!box)return;const all=sshLiveFeedRows();for(const x of all)upsertSSHLiveFeedCard(x.session.id);syncSSHLiveFeedOrder(all);updateSSHLiveFeedSummary(all);requestAnimationFrame(()=>box.querySelectorAll('.ssh-live-card-events').forEach(events=>{events.scrollTop=events.scrollHeight;}));}
function renderSSHHighlights(){
  const body=$('sshHighlightsBody');if(!body)return;
  body.innerHTML=sshHighlights.map(h=>{const tags=(h.tags||[]).map(t=>`<span class="ssh-highlight-tag">${esc(t)}</span>`).join('');return `<tr data-ssh-highlight-id="${esc(h.session_id)}"><td>${esc(dt(h.at))}</td><td>${ipLinkHTML(h.ip)}</td><td>${esc(h.country||'—')}</td><td><span class="highlight-rating ${esc(h.rating)}">${esc(h.rating)}</span></td><td><span class="ssh-highlight-score ${esc(h.rating)}">${h.score}/100</span></td><td><span class="ssh-highlight-title" title="${esc(h.title)}">${esc(h.title)}</span>${tags?`<span class="ssh-highlight-tags">${tags}</span>`:''}<span class="ssh-highlight-reason" title="${esc(h.reason)}">${esc(h.reason)}</span></td><td>${h.commands||0}</td><td>${esc(duration((h.duration_seconds||0)*1000))}</td><td>${h.depth||0}</td></tr>`;}).join('')||'<tr><td colspan="9"><small>No SSH highlights match this rating yet.</small></td></tr>';
  $('sshHighlightsCount').textContent=`${sshHighlights.length} loaded · authenticated + noteworthy`;
  document.querySelectorAll('#sshHighlightsBody [data-ssh-highlight-id]').forEach(tr=>tr.onclick=()=>openSSHSession(tr.dataset.sshHighlightId));
}
async function loadSSHHighlights(reset=false){
  if(sshHighlightLoading||(!reset&&sshHighlightExhausted))return;
  sshHighlightLoading=true;if($('sshHighlightsLoading'))$('sshHighlightsLoading').hidden=false;
  if(reset){sshHighlights=[];sshHighlightNext='';sshHighlightExhausted=false;updateSSHHighlightsExport();renderSSHHighlights();}
  try{let url='/api/ssh/highlights?limit=20&rating='+encodeURIComponent(sshHighlightFilter)+rangeAmp(false);if(!reset&&sshHighlightNext)url+='&before='+encodeURIComponent(sshHighlightNext);const page=await api(url),items=page.items||[];const known=new Set(sshHighlights.map(x=>x.session_id));for(const h of items)if(!known.has(h.session_id)){sshHighlights.push(h);known.add(h.session_id)}sshHighlightNext=page.next_before||'';sshHighlightExhausted=!sshHighlightNext||items.length===0;renderSSHHighlights();}catch(e){console.error(e)}finally{sshHighlightLoading=false;if($('sshHighlightsLoading'))$('sshHighlightsLoading').hidden=true;}
}
function updateSSHHighlightsExport(){const a=$('sshHighlightsExportJSON');if(!a)return;const q=new URLSearchParams();q.set('rating',sshHighlightFilter);const tr=selectedTimeRange();if(selectedDateMode==='all')q.set('all','1');if(tr.from)q.set('from',tr.from);if(tr.to)q.set('to',tr.to);a.href='/api/ssh/highlights/export.json?'+q.toString();}
function setSSHHighlightFilter(filter){sshHighlightFilter=filter;document.querySelectorAll('#sshHighlightFilters [data-highlight-filter]').forEach(b=>b.classList.toggle('active',b.dataset.highlightFilter===filter));updateSSHHighlightsExport();loadSSHHighlights(true);}

let trustedSettings={manual:[],proxy:[]};
async function loadTrustedSettings(){try{trustedSettings=await api('/api/settings/trusted-domains');renderTrustedSettings();}catch(e){console.error(e)}}
function renderTrustedSettings(){const manual=(trustedSettings.manual||[]).map(x=>x.domain).sort();$('trustedDomainsInput').value=manual.join('\n');const proxy=trustedSettings.proxy||[];$('proxyTrustedDomains').innerHTML=proxy.map(x=>`<div class="trusted-domain-row"><b>${esc(x.domain)}</b><span>${esc(x.integration||'verified proxy')}</span></div>`).join('')||'<small>No proxy-trusted targets yet.</small>';}
async function openSettings(){await loadTrustedSettings();$('settingsModal').classList.add('open');$('settingsBackdrop').classList.add('open');$('settingsModal').setAttribute('aria-hidden','false');$('settingsBackdrop').setAttribute('aria-hidden','false');document.body.classList.add('overlay-scroll-lock');$('settingsStatus').textContent='';}
function closeSettings(){$('settingsModal').classList.remove('open');$('settingsBackdrop').classList.remove('open');$('settingsModal').setAttribute('aria-hidden','true');$('settingsBackdrop').setAttribute('aria-hidden','true');syncOverlayBodyLock();}
function openHelp(){$('helpModal').classList.add('open');$('helpBackdrop').classList.add('open');$('helpModal').setAttribute('aria-hidden','false');$('helpBackdrop').setAttribute('aria-hidden','false');syncOverlayBodyLock();}
function closeHelp(){$('helpModal').classList.remove('open');$('helpBackdrop').classList.remove('open');$('helpModal').setAttribute('aria-hidden','true');$('helpBackdrop').setAttribute('aria-hidden','true');syncOverlayBodyLock();}
async function saveTrustedSettings(){
  const domains=$('trustedDomainsInput').value.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean),button=$('saveSettings'),original='Save trusted domains';
  clearTimeout(trustedSaveFeedbackTimer);trustedSaveFeedbackTimer=0;
  button.disabled=true;button.classList.remove('saved');button.classList.add('saving');button.textContent='Saving…';$('settingsStatus').textContent='';
  try{
    const r=await adminWriteFetch('/api/settings/trusted-domains',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({domains})});
    if(!r.ok){const msg=(await r.text()).trim();throw new Error(msg||String(r.status));}
    trustedSettings=await r.json();renderTrustedSettings();selectedTarget='';await refreshCurrentView();
    button.classList.remove('saving');button.classList.add('saved');button.textContent='Gespeichert ✓';button.disabled=false;
    trustedSaveFeedbackTimer=setTimeout(()=>{button.classList.remove('saved');button.textContent=original;trustedSaveFeedbackTimer=0;},5000);
  }catch(e){button.classList.remove('saving','saved');button.textContent=original;button.disabled=false;$('settingsStatus').textContent=e.message||'save failed';console.error(e)}
}

function ipTopListHTML(rows){return (rows||[]).map(x=>`<div><span title="${esc(x.value)}">${esc(short(x.value,48))}</span><b>${Number(x.count||0).toLocaleString()}</b></div>`).join('')||'<small>No observations retained.</small>';}
function renderIPTimeline(rows){const data=rows||[];renderDualTimeline($('ipTimelineChart'),data,'day');if($('ipTimelineFirst'))$('ipTimelineFirst').textContent=data.length?chartTimeLabel(data[0].at,'day'):'first';if($('ipTimelineLast'))$('ipTimelineLast').textContent=data.length?chartTimeLabel(data[data.length-1].at,'day'):'last';if($('ipTimelineUnit'))$('ipTimelineUnit').textContent='events / day';}
function mergedIPTimeline(d){const rows=[];for(const e of (d.http_events||[]))rows.push({at:e.at,proto:'WEB',kind:e.method||e.category||'HTTP',summary:`${e.method||'GET'} ${e.path||'/'}`,risk:e.risk_score||0});for(const e of (d.ssh_events||[]))rows.push({at:e.at,proto:'SSH',kind:sshLiveEventLabel(e.type),summary:e.command||e.message||e.type,risk:e.risk_score||0});for(const e of (d.intelligence||[]))rows.push({at:e.at,proto:(e.protocol||'INTEL').toUpperCase(),kind:(e.kind||'intel').toUpperCase(),summary:e.summary||e.url||e.host||'intelligence',risk:0});rows.sort((a,b)=>new Date(b.at)-new Date(a.at));return rows.slice(0,300);}
function renderIPIntelligence(d){const s=d.summary||{},a=d.actor||{};currentIPView=d.ip||'';$('ipViewTitle').textContent=`IP Intelligence · ${d.ip||'—'}`;$('ipViewSubtitle').textContent=`${countryLabel(a.country)} · ${(a.protocols||[]).join(' + ')||'no protocol'} · first ${dt(s.first_seen)} · last ${dt(s.last_seen)}`;$('ipExportJSON').href='/api/ip/'+encodeURIComponent(d.ip)+'/export.json';$('ipRisk').textContent=(s.risk_score||0)+'/100';$('ipClassification').textContent=`${s.classification||'—'} · ${s.actor||'unknown'}`;$('ipSSHConnections').textContent=(s.ssh_connections||0).toLocaleString();$('ipSSHAuth').textContent=`${s.ssh_auth_accepted||0} accepted · ${s.ssh_auth_rejected||0} rejected`;$('ipSSHUsers').textContent=(s.ssh_unique_users||0).toLocaleString();$('ipSSHRate').textContent=`peak ${s.ssh_peak_attempts_per_minute||0} auth/min`;$('ipSSHConcurrent').textContent=(s.ssh_peak_concurrent||0).toLocaleString();$('ipSSHRevisit').textContent=s.ssh_median_revisit_seconds?`revisit ${s.ssh_median_revisit_seconds}s · jitter ${s.ssh_revisit_jitter_seconds||0}s`:'revisit —';$('ipHTTPRequests').textContent=(s.http_requests||0).toLocaleString();$('ipHTTPShape').textContent=`${s.http_unique_paths||0} paths · ${s.http_unique_targets||0} targets · peak ${s.http_peak_requests_per_minute||0}/min`;$('ipEngagement').textContent=duration((s.engagement_seconds||0)*1000);$('ipSeen').textContent=`depth ${s.depth||0} · ${since(s.last_seen)} since last`;$('ipPayloads').textContent=(s.payload_signals||0).toLocaleString();$('ipCanaries').textContent=(s.canary_touches||0).toLocaleString();renderIPTimeline(d.timeline||[]);$('ipReasons').innerHTML=(s.reasons||[]).map(x=>`<span>${esc(x)}</span>`).join('')||'<small>No additional behavior reasons retained.</small>';$('ipTopUsers').innerHTML=ipTopListHTML(d.top_usernames);$('ipTopClients').innerHTML=ipTopListHTML(d.top_ssh_clients);$('ipTopCommands').innerHTML=ipTopListHTML(d.top_commands);$('ipTopFamilies').innerHTML=ipTopListHTML(d.top_command_families);$('ipTopPaths').innerHTML=ipTopListHTML(d.top_paths);$('ipTopTargets').innerHTML=ipTopListHTML(d.top_targets);$('ipCampaignBody').innerHTML=(d.possible_campaign_peers||[]).map(x=>`<tr><td>${ipLinkHTML(x.ip)}</td><td>${esc(x.country||'—')}</td><td><b>${x.confidence||0}%</b></td><td>${x.risk_score||0}</td><td>${since(x.last_seen)}</td><td class="path" title="${esc((x.reasons||[]).join(', '))}">${esc(short((x.reasons||[]).join(' · ')||'—',80))}</td></tr>`).join('')||'<tr class="empty-row"><td colspan="6">No strong campaign correlations retained.</td></tr>';const timeline=mergedIPTimeline(d);$('ipRawCounts').textContent=`${(d.http_sessions||[]).length} Web sessions · ${(d.ssh_sessions||[]).length} SSH sessions · ${(d.http_events||[]).length+(d.ssh_events||[]).length} events · ${(d.intelligence||[]).length} intel`;$('ipObservedTimeline').innerHTML=timeline.map(x=>`<div><time>${esc(dt(x.at))}</time><span class="ip-proto ${x.proto==='SSH'?'ssh':'web'}">${esc(x.proto)}</span><b>${esc(x.kind)}</b><span title="${esc(x.summary)}">${esc(short(x.summary,110))}</span>${x.risk?`<strong>${x.risk}</strong>`:''}</div>`).join('')||'<small>No retained events.</small>';}
