function applyAdminView(refreshData=true){const hash=location.hash||'';adminView=hash==='#live'?'live':hash.startsWith('#ip/')?'ip':'dashboard';const live=adminView==='live',ipMode=adminView==='ip';$('dashboardView').hidden=live||ipMode;$('liveView').hidden=!live;$('ipView').hidden=!ipMode;updateViewSwitch();if(live&&selectedDateMode!=='live'){selectedDateMode='live';if($('dateFilter'))$('dateFilter').value='live';resetGlobalLazy();updateRangeLabels();syncLiveStreams();}if(live){renderLiveWebSessions(webLiveRows);renderLiveSSHSessions(sshLiveRows);renderSSHLiveFeed();}else if(ipMode){let ip='';try{ip=decodeURIComponent(hash.slice(4));}catch(e){}currentIPView=ip;if(refreshData)loadIPView(ip);}else if(sshHighlights.length===0&&!sshHighlightLoading)loadSSHHighlights(true);if(refreshData&&adminView!=='ip')refreshCurrentView();window.scrollTo({top:0,behavior:'auto'});}
