function syncOverlayBodyLock(){const overlayOpen=[$('settingsModal'),$('helpModal'),$('drawer'),$('sshDrawer'),$('actorDrawer')].some(el=>el&&el.classList.contains('open'));document.body.classList.toggle('overlay-scroll-lock',overlayOpen);}function closeDrawer(){openWebSessionId='';openWebSessionData=null;httpDrawerPending=0;if($('httpNewEvents'))$('httpNewEvents').hidden=true;$('drawer').classList.remove('open');$('drawer').setAttribute('aria-hidden','true');if(!$('sshDrawer').classList.contains('open')&&!$('actorDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeSSHDrawer(){openSSHSessionId='';openSSHSessionData=null;sshDrawerPending=0;$('sshNewEvents').hidden=true;$('sshDrawer').classList.remove('open');$('sshDrawer').setAttribute('aria-hidden','true');if(!$('drawer').classList.contains('open')&&!$('actorDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeActorDrawer(){$('actorDrawer').classList.remove('open');$('actorDrawer').setAttribute('aria-hidden','true');if(!$('drawer').classList.contains('open')&&!$('sshDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeAllDrawers(){closeDrawer();closeSSHDrawer();closeActorDrawer();$('shade').classList.remove('open');syncOverlayBodyLock()}$('closeDrawer').onclick=closeDrawer;$('closeSSHDrawer').onclick=closeSSHDrawer;$('closeActorDrawer').onclick=closeActorDrawer;$('dIPHistory').onclick=()=>{const ip=String(openWebSessionData?.session?.ip||'').trim();closeDrawer();openIPView(ip);};$('shade').onclick=closeAllDrawers;
function scheduleIPViewRefresh(ip){if(adminView!=='ip'||!currentIPView||String(ip||'')!==currentIPView)return;clearTimeout(ipViewRefreshTimer);ipViewRefreshTimer=setTimeout(()=>{ipViewRefreshTimer=0;loadIPView(currentIPView);},350);}
function handleRealtimeWeb(msg){const e=msg.event,snapshot=msg.session;if(!e)return;scheduleIPViewRefresh(e.ip);appendOpenWebEvent(e,snapshot);if(!selectedTimeRange().live||!eventMatchesSelectedTarget(e))return;if(snapshot)updateLiveSessionSnapshot('web',snapshot);recentEvents.unshift(e);recentEvents=recentEvents.slice(0,Math.max(240,lazyLimits.httpEvents));const box=$('events');if(box){box.insertAdjacentHTML('afterbegin',eventHTML(e));while(box.children.length>lazyLimits.httpEvents)box.lastElementChild.remove();}if(adminView==='dashboard')applyRealtimeActivity('web',e);}
function handleRealtimeSSH(msg){const e=msg.ssh_event,snapshot=msg.ssh_session;if(!e||!selectedTimeRange().live)return;scheduleIPViewRefresh(e.ip);applySSHLiveFeedEvent(e,snapshot);appendOpenSSHEvent(e,snapshot);if(snapshot)updateLiveSessionSnapshot('ssh',snapshot);sshRecentEvents.unshift(e);sshRecentEvents=sshRecentEvents.slice(0,Math.max(160,lazyLimits.sshEvents));if(sshActivityEvent(e)&&adminView==='dashboard')applyRealtimeActivity('ssh',e);const box=$('sshEvents');if(box){box.insertAdjacentHTML('afterbegin',sshEventHTML(e));while(box.children.length>lazyLimits.sshEvents)box.lastElementChild.remove();}}
function scheduleRealtimeResync(){clearTimeout(realtimeResyncTimer);realtimeResyncTimer=setTimeout(()=>{realtimeResyncTimer=0;refreshCurrentView();},200);}
function connectRealtime(){if(realtimeSocket||!selectedTimeRange().live)return;clearTimeout(realtimeReconnectTimer);const scheme=location.protocol==='https:'?'wss:':'ws:';let opened=false,ws;try{ws=new WebSocket(`${scheme}//${location.host}/api/realtime`);}catch(e){realtimeReconnectTimer=setTimeout(connectRealtime,realtimeReconnectDelay);realtimeReconnectDelay=Math.min(15000,realtimeReconnectDelay*2);return;}realtimeSocket=ws;ws.onopen=()=>{opened=true;realtimeReconnectDelay=1200;};ws.onmessage=ev=>{try{const msg=JSON.parse(ev.data);if(msg.type==='web')handleRealtimeWeb(msg);else if(msg.type==='ssh')handleRealtimeSSH(msg);else if(msg.type==='resync_required')scheduleRealtimeResync();}catch(err){}};ws.onclose=()=>{if(realtimeSocket===ws)realtimeSocket=null;if(opened)scheduleRealtimeResync();if(selectedTimeRange().live){ensureAdminSession().then(ok=>{if(!ok)return;clearTimeout(realtimeReconnectTimer);const wait=realtimeReconnectDelay;realtimeReconnectDelay=Math.min(15000,realtimeReconnectDelay*2);realtimeReconnectTimer=setTimeout(connectRealtime,wait);}).catch(()=>{});}};ws.onerror=()=>{try{ws.close();}catch(e){}};}
function syncLiveStreams(){const live=selectedTimeRange().live;if(live){connectRealtime();return;}clearTimeout(realtimeReconnectTimer);realtimeReconnectTimer=0;realtimeReconnectDelay=1200;if(realtimeSocket){const ws=realtimeSocket;realtimeSocket=null;try{ws.close();}catch(e){}}}
